def parse_utc_us(value: str) -> int:
    from datetime import datetime, timezone
    if not isinstance(value, str) or not value.endswith("Z"):
        raise FailClosed("PC6_TIMESTAMP_NOT_UTC")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.tzinfo is None or parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise FailClosed("PC6_TIMESTAMP_NOT_UTC")
    return int(parsed.timestamp() * 1_000_000)


def format_utc(us: int) -> str:
    from datetime import datetime, timezone
    return datetime.fromtimestamp(us / 1_000_000, tz=timezone.utc).strftime(
        "%Y-%m-%dT%H:%M:%SZ")


T1_GRID_START_US = parse_utc_us(T1_GRID_START_UTC)
T1_GRID_END_US = parse_utc_us(T1_GRID_END_UTC)
W1_DEV_LABEL_BOUNDARY_US = parse_utc_us(W1_DEV_LABEL_BOUNDARY_UTC)
W1_LAST_DECISION_US = {h: parse_utc_us(v) for h, v in W1_LAST_DECISION_UTC.items()}
# Frozen self-consistency: last admissible decision + h == development boundary.
for _h, _last in W1_LAST_DECISION_US.items():
    if _last + _h * US_PER_HOUR != W1_DEV_LABEL_BOUNDARY_US:
        raise AssertionError("frozen W1 window constants inconsistent")
# T1 label support ends at last decision exit t+8h (prereg V3 section 11.2).
T1_ALLOWED_LABEL_END_US = T1_GRID_END_US + GRID_STEP_US


def t1_decision_grid_us() -> list[int]:
    grid = list(range(T1_GRID_START_US, T1_GRID_END_US + 1, GRID_STEP_US))
    if len(grid) != T1_CALENDAR_MAX_T or grid[-1] != T1_GRID_END_US:
        raise FailClosed("T1_FROZEN_GRID_CONSTRUCTION_FAILED")
    return grid


def w1_decision_grid_us() -> list[int]:
    return [ts for ts in t1_decision_grid_us() if ts <= W1_LAST_DECISION_US[8]]


def validate_decision_grid(ts_list_us: list[int], kind: str, synthetic: bool) -> dict[str, Any]:
    """F04: exact decision-time/window enforcement.

    Every timestamp must lie exactly on the frozen 8h grid (00/08/16 UTC)
    inside the frozen window, strictly increasing (no duplicate, no reorder).
    In production (non-synthetic) the population must be the EXACT full frozen
    population: 3378 timestamps for T1; the full sub-grid up to the frozen
    8h last admissible decision for W1.  Synthetic fixtures may use an exact
    subset but can never leave the frozen grid.
    """
    if not isinstance(ts_list_us, list) or not ts_list_us or \
            not all(isinstance(item, int) for item in ts_list_us):
        raise FailClosed("PC6_DECISION_GRID_INVALID")
    previous = None
    for ts in ts_list_us:
        if previous is not None and ts <= previous:
            raise FailClosed("PC6_DECISION_GRID_DUPLICATE_OR_REORDERED")
        if ts < T1_GRID_START_US or ts > T1_GRID_END_US:
            raise FailClosed("PC6_DECISION_OUTSIDE_FROZEN_WINDOW")
        if (ts - T1_GRID_START_US) % GRID_STEP_US != 0:
            raise FailClosed("PC6_DECISION_OFF_GRID")
        if ((ts // US_PER_HOUR) % 24) not in ALLOWED_UTC_SLOT_HOURS:
            raise FailClosed("PC6_DECISION_OFF_UTC_SLOT")
        previous = ts
    if kind == "W1" and ts_list_us[-1] > W1_LAST_DECISION_US[8]:
        raise FailClosed("W1_DECISION_BEYOND_FROZEN_LAST_ADMISSIBLE")
    if not synthetic:
        expected = t1_decision_grid_us() if kind == "T1" else w1_decision_grid_us()
        if ts_list_us != expected:
            raise FailClosed("PC6_DECISION_GRID_POPULATION_MISMATCH")
    return {
        "kind": kind,
        "count": len(ts_list_us),
        "first_utc": format_utc(ts_list_us[0]),
        "last_utc": format_utc(ts_list_us[-1]),
        "step_hours": GRID_STEP_HOURS,
        "calendar_max_t": T1_CALENDAR_MAX_T,
        "grid_sha256": sha_json(ts_list_us),
    }


def w1_admissible(ts_us: int, horizon_hours: int) -> bool:
    if horizon_hours not in W1_LAST_DECISION_US:
        raise FailClosed("W1_HORIZON_INVALID")
    return ts_us <= W1_LAST_DECISION_US[horizon_hours]


