def load_source(raw: bytes) -> dict[str, Any]:
    try:
        source = json.loads(raw)
    except ValueError as exc:
        raise FailClosed("PC6_SOURCE_PARSE_FAILED") from exc
    if not isinstance(source, dict) or source.get("schema") != SOURCE_SCHEMA:
        raise FailClosed("PC6_SOURCE_SCHEMA_MISMATCH")
    symbols = source.get("symbols")
    if not isinstance(symbols, dict) or not symbols:
        raise FailClosed("PC6_SOURCE_SYMBOLS_INVALID")
    grid = source.get("decision_grid_ts_utc")
    if not isinstance(grid, list) or not grid:
        raise FailClosed("PC6_SOURCE_GRID_MISSING")
    for symbol, table in symbols.items():
        if not isinstance(table, dict):
            raise FailClosed("PC6_SOURCE_SYMBOLS_INVALID")
        for field in ("perp_bars", "spot_bars"):
            bars = table.get(field)
            if not isinstance(bars, list):
                raise FailClosed("PC6_SOURCE_BARS_INVALID")
            previous = None
            for bar in bars:
                if not isinstance(bar, dict) or "close_us" not in bar or "close" not in bar:
                    raise FailClosed("PC6_SOURCE_BARS_INVALID")
                close_us = bar["close_us"]
                if not isinstance(close_us, int) or (previous is not None and close_us <= previous):
                    raise FailClosed("PC6_SOURCE_BARS_UNORDERED")
                if not isinstance(bar["close"], (int, float)) or not math.isfinite(float(bar["close"])):
                    raise FailClosed("PC6_SOURCE_BARS_INVALID")
                previous = close_us
        events = table.get("funding_events", [])
        if not isinstance(events, list):
            raise FailClosed("PC6_SOURCE_FUNDING_INVALID")
        previous = None
        for event in events:
            if not isinstance(event, dict) or "market_event_time_us" not in event \
                    or "funding_rate" not in event:
                raise FailClosed("PC6_SOURCE_FUNDING_INVALID")
            when = event["market_event_time_us"]
            if not isinstance(when, int) or (previous is not None and when <= previous):
                raise FailClosed("PC6_SOURCE_FUNDING_UNORDERED")
            if not math.isfinite(float(event["funding_rate"])):
                raise FailClosed("PC6_SOURCE_FUNDING_INVALID")
            previous = when
    return source


def _snapshot(bars: list[Mapping[str, Any]], at_us: int) -> Mapping[str, Any] | None:
    try:
        return evaluator.previous_fully_closed_bar(bars, at_us)
    except evaluator.EvaluationError:
        return None


def candidate_lookback_days(candidate: Mapping[str, Any]) -> int | None:
    raw = candidate.get("lookback")
    if raw in _NON_NUMERIC_LOOKBACKS:
        return None
    if isinstance(raw, bool) or not isinstance(raw, int) or raw <= 0:
        raise FailClosed("W1_CANDIDATE_LOOKBACK_INVALID")
    return raw


# ---------------------------------------------------------------------------
# Feature derivation (outcome blind; decision-time information only).
# ---------------------------------------------------------------------------

def derive_features(source: Mapping[str, Any], grid_ts_us: list[int], kind: str,
                    header: Mapping[str, Any],
                    candidates_by_id: Mapping[str, Mapping[str, Any]] | None = None,
                    order: list[str] | None = None) -> dict[str, Any]:
    symbols = sorted(source["symbols"])
    histories: dict[str, dict[str, list[float]]] = {
        symbol: {"basis": [], "spot_returns": [], "perp_returns": [],
                 "quote_volume": [], "signed_quote_volume": []}
        for symbol in symbols
    }
    last_close: dict[str, tuple[float, float] | None] = {symbol: None for symbol in symbols}
    cohorts: list[dict[str, Any]] = []
    for index, ts in enumerate(grid_ts_us):
        base_features: dict[str, float] = {}
        defined_now: dict[str, bool] = {}
        for symbol in symbols:
            table = source["symbols"][symbol]
            perp = _snapshot(table["perp_bars"], ts)
            spot = _snapshot(table["spot_bars"], ts)
            defined = perp is not None and spot is not None and \
                float(perp["close"]) > 0 and float(spot["close"]) > 0
            defined_now[symbol] = defined
            if not defined:
                last_close[symbol] = None
                continue
            perp_close = float(perp["close"])
            spot_close = float(spot["close"])
            basis = float(evaluator.log_basis(FLOAT(perp_close), FLOAT(spot_close)))
            history = histories[symbol]
            history["basis"].append(basis)
            previous = last_close[symbol]
            if previous is not None:
                history["perp_returns"].append(perp_close / previous[0] - 1.0)
                history["spot_returns"].append(spot_close / previous[1] - 1.0)
            last_close[symbol] = (perp_close, spot_close)
            volume = perp.get("quote_volume")
            signed = perp.get("signed_quote_volume")
            if isinstance(volume, (int, float)) and math.isfinite(float(volume)) and \
                    isinstance(signed, (int, float)) and math.isfinite(float(signed)):
                history["quote_volume"].append(float(volume))
                history["signed_quote_volume"].append(float(signed))
            base_features[symbol] = basis
        cohort: dict[str, Any] = {
            "cohort_id": index,
            "decision_ts_utc": format_utc(ts),
            "decision_us": ts,
            "features": dict(sorted(base_features.items())),
        }
        if kind == "W1":
            if candidates_by_id is None or order is None:
                raise FailClosed("W1_CANDIDATE_SET_REQUIRED")
            candidate_features: dict[str, dict[str, float]] = {}
            for candidate_id in order:
                candidate = candidates_by_id[candidate_id]
                core = candidate.get("signal_core")
                lookback = candidate_lookback_days(candidate)
                values: dict[str, float] = {}
                for symbol in symbols:
                    if not defined_now[symbol]:
                        continue
                    value = _candidate_feature_value(core, histories[symbol], lookback)
                    if value is not None:
                        values[symbol] = value
                candidate_features[candidate_id] = dict(sorted(values.items()))
            cohort["candidate_features"] = candidate_features
        cohorts.append(cohort)
    grid_identity = validate_decision_grid(grid_ts_us, kind,
                                           os.environ.get("P5_SYNTHETIC_MODE") == "1")
    horizons = (8,) if kind == "T1" else W1_HORIZONS
    document = {
        "schema": FEATURES_SCHEMA,
        "kind": kind,
        "decision_grid": grid_identity,
        "allowed_label_end_us_by_horizon": {
            str(h): allowed_label_end_us(kind, h) for h in horizons
        },
        "cohorts": cohorts,
    }
    document.update(dict(header))
    return document


def _candidate_feature_value(core: Any, history: Mapping[str, list[float]],
                             lookback_days: int | None) -> float | None:
    minimum = _MIN_HISTORY.get(core)
    basis_len = len(history["basis"])
    if minimum is not None and basis_len < minimum:
        return None
    if minimum is None:
        if lookback_days is None:
            return None
        needed = _CYCLES_PER_DAY * lookback_days
        required_fields = {
            "BASIS_PERSISTENCE_L": ("basis",),
            "BM_EQ70_L": ("spot_returns", "perp_returns"),
            "PV_L": ("quote_volume",),
            "PV_VAR_L": ("quote_volume",),
            "PV_IMB_L": ("signed_quote_volume",),
            "PV_IMB_VAR_L": ("signed_quote_volume",),
            "DAMIHUD_L": ("quote_volume", "perp_returns"),
        }.get(core)
        if required_fields is None:
            raise FailClosed("W1_CANDIDATE_CORE_UNKNOWN")
        if any(len(history[field]) < needed for field in required_fields):
            return None
    arrays = {key: np.asarray(values, dtype=np.float64)
              for key, values in history.items()}
    try:
        value = evaluator.feature_value(str(core), arrays, lookback_days)
    except evaluator.EvaluationError:
        return None
    result = float(value)
    if not math.isfinite(result):
        return None
    return result


# ---------------------------------------------------------------------------
# Outcome derivation (only after APPLIED + durable label-access marker).
# ---------------------------------------------------------------------------

def derive_outcomes(source: Mapping[str, Any], grid_ts_us: list[int], kind: str,
                    header: Mapping[str, Any], marker_recorded: bool) -> dict[str, Any]:
    if marker_recorded is not True:
        raise FailClosed("PC6_OUTCOME_DERIVATION_BEFORE_LABEL_MARKER")
    horizons = (8,) if kind == "T1" else W1_HORIZONS
    symbols = sorted(source["symbols"])
    cohorts: list[dict[str, Any]] = []
    label_end: dict[str, int] = {}
    for index, ts in enumerate(grid_ts_us):
        by_horizon: dict[str, dict[str, dict[str, float]]] = {}
        for h in horizons:
            if kind == "W1" and not w1_admissible(ts, h):
                continue
            exit_us = ts + h * US_PER_HOUR
            allowed = allowed_label_end_us(kind, h)
            if exit_us > allowed:
                raise FailClosed("PC6_LABEL_BEYOND_FROZEN_WINDOW")
            labels: dict[str, dict[str, float]] = {}
            for symbol in symbols:
                table = source["symbols"][symbol]
                entry_perp = _snapshot(table["perp_bars"], ts)
                entry_spot = _snapshot(table["spot_bars"], ts)
                exit_perp = _snapshot(table["perp_bars"], exit_us)
                exit_spot = _snapshot(table["spot_bars"], exit_us)
                if entry_perp is None or entry_spot is None or \
                        exit_perp is None or exit_spot is None:
                    continue
                if int(exit_perp["close_us"]) <= ts or int(exit_spot["close_us"]) <= ts:
                    continue  # no post-decision bar: label undefined, not fabricated
                prices = [float(entry_perp["close"]), float(exit_perp["close"]),
                          float(entry_spot["close"]), float(exit_spot["close"])]
                if any(p <= 0 or not math.isfinite(p) for p in prices):
                    continue
                funding = evaluator.funding_in_open_closed(
                    table.get("funding_events", []), ts, exit_us, FLOAT(1.0))
                components = evaluator.return_components(
                    FLOAT(prices[0]), FLOAT(prices[1]), FLOAT(prices[2]),
                    FLOAT(prices[3]), funding)
                labels[symbol] = {field: float(components[field])
                                  for field in ("TOTAL", "SPOT", "TERM", "FUNDING")}
            by_horizon[str(h)] = labels
            label_end[str(h)] = max(label_end.get(str(h), 0), exit_us)
        cohorts.append({
            "cohort_id": index,
            "decision_us": ts,
            "labels_by_horizon": by_horizon,
        })
    document = {
        "schema": OUTCOMES_SCHEMA,
        "kind": kind,
        "derivation": "DAEMON_POST_MARKER_ON_DEMAND",
        "label_end_us_by_horizon": label_end,
        "cohorts": cohorts,
    }
    if source.get("synthetic_force_t1_integrity_void") is True:
        document["synthetic_force_t1_integrity_void"] = True
    document.update(dict(header))
    return document


# ---------------------------------------------------------------------------
# F05 turnover / net fee-only diagnostic helpers (prereg V3 section 12).
# ---------------------------------------------------------------------------

def turnover_between(previous_weights: Mapping[str, Any],
                     current_weights: Mapping[str, Any]) -> np.float64:
    union = set(previous_weights) | set(current_weights)
    total = FLOAT(0.0)
    for symbol in sorted(union):
        w_now = FLOAT(current_weights.get(symbol, 0.0))
        w_prev = FLOAT(previous_weights.get(symbol, 0.0))
        total = FLOAT(total + np.abs(w_now - w_prev))
    return total


def turnover_series_for_frozen(frozen_rows: list[Mapping[str, Any]]) -> list[np.float64 | None]:
    """Per-cohort traded notional per prereg V3 section 12: entry notional 2.0
    at the first evaluable cycle, consecutive-cohort L1 weight change at
    interior cycles, and exit notional 2.0 added at the last evaluable cycle.
    Non-FROZEN cycles carry None (no traded notional defined)."""
    values: list[np.float64 | None] = [None] * len(frozen_rows)
    previous_weights: Mapping[str, Any] | None = None
    evaluable_indices = [index for index, row in enumerate(frozen_rows)
                         if row.get("state") == "FROZEN"]
    for index in evaluable_indices:
        weights = frozen_rows[index]["weights"]
        if previous_weights is None:
            values[index] = FLOAT(ENTRY_TRADE_NOTIONAL)
        else:
            values[index] = turnover_between(previous_weights, weights)
        previous_weights = weights
    if evaluable_indices:
        last = evaluable_indices[-1]
        values[last] = FLOAT(values[last] + EXIT_TRADE_NOTIONAL)
    return values


def net_fee_only_mean(estimator_totals: list[np.float64],
                      estimator_turnovers: list[np.float64]) -> float:
    """GROSS-minus-fee net mean over estimator (OUTCOME_COMPLETE) cohorts:
    mean(R(t) - 0.000500 * turnover(t)); prereg V3 sections 7/12."""
    if len(estimator_totals) != len(estimator_turnovers) or not estimator_totals:
        raise FailClosed("NET_FEE_ONLY_INPUT_MISMATCH")
    net = np.asarray(
        [FLOAT(total) - TAKER_FEE_PER_UNIT_NOTIONAL * FLOAT(turnover)
         for total, turnover in zip(estimator_totals, estimator_turnovers)],
        dtype=np.float64)
    return float(np.mean(net, dtype=np.float64))


# ---------------------------------------------------------------------------
# F07 exhaustive DEVELOPMENT_REJECTED rules (W1 contract section 6).
# ---------------------------------------------------------------------------

def development_rejection_reason(candidate: Mapping[str, Any],
                                 feature_rows: list[Mapping[str, float]],
                                 frozen_rows: list[Mapping[str, Any]],
                                 seen_candidate_hashes: set[str],
                                 seen_weight_paths: set[str]) -> str | None:
    """Outcome-free rejection, evaluated in frozen enumeration order BEFORE any
    W1 label access.  Rules exactly as W1 contract section 6 (exhaustive):
    1. FORMULA_UNDEFINED_ON_FROZEN_INPUTS, 2. EXACT_ZERO_XS_VARIANCE,
    3. DUPLICATE_CANDIDATE_HASH, 4. DUPLICATE_WEIGHT_PATH."""
    if candidate.get("neutralization") != "NONE":
        raise evaluator.EvaluationError("EQ71_REFUSED")
    evaluable = [index for index, row in enumerate(frozen_rows)
                 if row.get("state") == "FROZEN"]
    reason: str | None = None
    if not evaluable:
        reason = "FORMULA_UNDEFINED_ON_FROZEN_INPUTS"
    if reason is None:
        all_zero_variance = True
        for index in evaluable:
            values = [FLOAT(value) for _, value in sorted(feature_rows[index].items())]
            if not values:
                all_zero_variance = False
                break
            array = np.asarray(values, dtype=np.float64)
            if array.max() != array.min():  # bitwise-exact float64 comparison
                all_zero_variance = False
                break
        if all_zero_variance:
            reason = "EXACT_ZERO_XS_VARIANCE"
    candidate_hash = evaluator.digest(evaluator.canonical_bytes(candidate))
    if reason is None and candidate_hash in seen_candidate_hashes:
        reason = "DUPLICATE_CANDIDATE_HASH"
    weight_path = sha_json([frozen_rows[index]["weight_path_sha256"]
                            for index in evaluable]) if evaluable else None
    if reason is None and weight_path is not None and weight_path in seen_weight_paths:
        reason = "DUPLICATE_WEIGHT_PATH"
    if reason is None:
        seen_candidate_hashes.add(candidate_hash)
        if weight_path is not None:
            seen_weight_paths.add(weight_path)
    if reason is not None and reason not in evaluator.REJECTION_RULES:
        raise FailClosed("W1_REJECTION_RULE_INVALID")
    return reason


def predicted_sign_prior(candidate: Mapping[str, Any]) -> int | None:
    declared = candidate.get("predicted_sign_under_fixed_construction")
    if declared == "POSITIVE":
        return 1
    if declared == "NEGATIVE":
        return -1
    if declared in (None, "UNDECLARED"):
        return None
    raise FailClosed("W1_SIGN_PRIOR_INVALID")
